import type { Person } from './person-model';
import type { RequestChecklist } from './request-checklist-model';
import type { Request } from './request-model';
import type { Workspace } from './workspace-model';

export interface RequestChecklistItem {
  /**
   * @displayName Request Checklist Item ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName ItemName
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  itemName: string;
  /**
   * @displayName Completed
   * @validationRule Required for create/update operations
   */
  completed: boolean;
  /**
   * @displayName CompletedAt
   * @validationRule Required for create/update operations
   */
  completedAt: string;
  /**
   * @displayName CompletedBy
   * @validationRule Required for create/update operations
   */
  completedBy: Pick<Person, 'id' | 'displayName'>;
  /**
   * @displayName RequestChecklistId
   * @validationRule Required for create/update operations
   */
  requestChecklistId: Pick<RequestChecklist, 'id' | 'checklistName'>;
  /**
   * @displayName RequestId
   * @validationRule Required for create/update operations
   */
  requestId: Pick<Request, 'id' | 'requestNumber'>;
  /**
   * @displayName WorkspaceId
   * @validationRule Required for create/update operations
   */
  workspaceId: Pick<Workspace, 'id' | 'workspaceName'>;
}

export const _RequestChecklistItem = 'RequestChecklistItem' as const;